<template>
 <section aria-label="共享病例去标识助手">
  <p>选择项目与患者的已授权资料，再检查待去标识的原文。模型只提出候选，修改和导出需人工复核。</p>
  <p v-if="!sessionAllowed" role="status">当前会话或角色不可使用病例去标识助手。</p>
  <p v-else-if="!configValid" role="alert">当前能力配置、模式或角色不允许新任务；不会退回通用模型。</p>
  <DeidentificationSharedInput v-if="sessionAllowed" :key="inputKey" :scope="scope" :patient-id="patientId" :initial-references="initialReferences" :active="active" :config-revision="feature?.revision??null" @scope-change="scopeChanged" @selection="selectionChanged" @availability="availabilityChanged" @invalidate="inputInvalidated"/>
  <template v-if="sessionAllowed">
   <el-input v-model="question" type="textarea" @input="questionMode='text'" aria-label="病例去标识原样可选问题" :disabled="!configValid" placeholder="可留空，填写本次需核对的问题"/>
   <small aria-label="补充问题长度">{{ Array.from(question).length }}/2000</small><p v-if="questionMode==='absent'">尚未填写补充问题。</p><p v-else-if="questionMode==='null'">传入的问题为空值；填写后将按原文提交。</p><details><summary>输入与保存详情</summary><p>问题 {{ Array.from(question).length }}/2000 个Unicode码点；不删除空白、BOM或改写换行。未提供、NULL与空文本分别保留。</p></details>
   <el-button :disabled="!canSubmit||busy" @click="preview">预览本次资料</el-button><el-button :disabled="!canSubmit||busy" @click="generate">查找去标识候选</el-button><el-button @click="clearAll">清除本次问题、选择与任务</el-button>
   <p v-if="busy" role="status">正在按当前用途核对与提交…</p><p v-if="error" role="alert">{{ error }}</p>
   <DeidentificationSharedFindings v-if="runId" :key="findingsKey" :run-id="runId" :scope="currentScope?.scope??null" :patient-id="currentScope?.patientId??null" :references="references" :expected-input="submittedInput" :active="active" :config-revision="feature?.revision??null" @metadata="metadataChanged" @invalidate="resultInvalidated" @close="closeTask"/>
   <DeidentificationSharedTasks :active="active" :case-id="references?.deidentification_case_id??null" @open="openTask"/>
  </template>
  <el-dialog :model-value="previewOpen&&sessionAllowed" title="病例去标识模型所见原件预览" append-to-body destroy-on-close @update:model-value="value=>{if(!value)closePreview()}">
   <p v-if="previewBusy">正在核对当前原件与唯一公开投影…</p><template v-if="previewValue"><p>下面只展示模型所见的完整所选来源和原问题；不发送私有Case、项目授权全文或未选文书。所选正文仍是临床信息，不称匿名。</p><pre aria-label="病例去标识模型完整公开来源">{{ JSON.stringify(previewValue.source,null,2) }}</pre><pre aria-label="病例去标识模型原问题">{{ previewValue.question }}</pre></template>
  </el-dialog>
 </section>
</template>
<script setup>
import{computed,nextTick,onActivated,onBeforeUnmount,onDeactivated,ref,watch}from'vue';import{useStore}from'vuex';
import DeidentificationSharedInput from'./DeidentificationSharedInput.vue';import DeidentificationSharedFindings from'./DeidentificationSharedFindings.vue';import DeidentificationSharedTasks from'./DeidentificationSharedTasks.vue';
import{previewDeidentificationTask,deidentificationTaskInputValid}from'@/api/ai/deidentificationTasks';import{verifyDeidentificationContext}from'@/api/ai/deidentificationResults';
import{createDeidentificationSharedTask,getDeidentificationSharedTask,verifyDeidentificationSharedMetadata}from'@/api/ai/deidentificationSharedTasks';
import{deidentificationCanonical as canonical,deidentificationId as uuid,positive,keys}from'@/api/ai/deidentificationCore';import{deidentificationPolicy}from'@/api/ai/deidentificationSources';
const props=defineProps({feature:{type:Object,default:null},scope:{type:Object,default:null},patientId:{type:Number,default:null},initialReferences:{type:Object,default:null},initialQuestion:{type:String,default:undefined},active:{type:Boolean,default:true}}),emit=defineEmits(['invalidate','run-created','scope-change']),store=useStore(),kept=ref(true),references=ref(null),available=ref(false),currentScope=ref(null),question=ref(''),questionMode=ref('absent'),submittedInput=ref(null),viewRevision=ref(0),busy=ref(false),error=ref(''),runId=ref(null),metadata=ref(null),previewOpen=ref(false),previewBusy=ref(false),previewValue=ref(null),inputNonce=ref(0);let epoch=0,previewEpoch=0,alive=true,timer=null,initialQuestionApplied=false;
const roles=computed(()=>store.state.user?.permissions),sessionAllowed=computed(()=>alive&&props.active&&kept.value&&!!store.state.user?.accessToken&&Array.isArray(roles.value)&&roles.value.every(x=>typeof x==='string')&&roles.value.some(x=>deidentificationPolicy.source_roles.includes(x))),configValid=computed(()=>{const f=props.feature;return sessionAllowed.value&&f?.key==='deidentification'&&f.engine==='llm'&&f.scope==='hospital'&&f.input_mode==='deidentification_evidence'&&f.enabled===true&&f.provider_configured===true&&f.validation_status!=='suspended'&&positive(f.revision)&&Array.isArray(f.allowed_roles)&&new Set(f.allowed_roles).size===f.allowed_roles.length&&f.allowed_roles.every(x=>deidentificationPolicy.source_roles.includes(x))&&roles.value.some(x=>f.allowed_roles.includes(x));}),selection=()=>({...references.value,...questionMode.value==='absent'?{}:{question:questionMode.value==='null'?null:question.value}}),canSubmit=computed(()=>configValid.value&&available.value&&references.value!==null&&deidentificationTaskInputValid(selection()));
const identity=()=>canonical([props.feature,props.scope,props.patientId,props.initialReferences,props.initialQuestion,props.active,store.state.user?.accessToken,store.state.user?.username,roles.value]),inputKey=computed(()=>identity()+':'+inputNonce.value),findingsKey=computed(()=>canonical([runId.value,viewRevision.value])),current=t=>sessionAllowed.value&&configValid.value&&t.epoch===epoch&&t.identity===identity();
function stopPolling(){if(timer!==null){clearTimeout(timer);timer=null;}}
function closePreview(){previewEpoch++;previewOpen.value=false;previewBusy.value=false;previewValue.value=null;}
function closeTask(){stopPolling();runId.value=null;metadata.value=null;submittedInput.value=null;}
function clearAll(){epoch++;stopPolling();references.value=null;available.value=false;currentScope.value=null;question.value='';questionMode.value='absent';initialQuestionApplied=false;busy.value=false;error.value='';closePreview();closeTask();inputNonce.value++;emit('invalidate');}
function scopeChanged(value){epoch++;stopPolling();references.value=null;available.value=false;question.value='';questionMode.value='absent';closePreview();closeTask();currentScope.value=value;emit('scope-change',value);}
function selectionChanged(value){epoch++;stopPolling();references.value=value;available.value=false;closePreview();closeTask();if(value&&!initialQuestionApplied&&props.initialReferences?.deidentification_case_id===value.deidentification_case_id){initialQuestionApplied=true;if(props.initialQuestion!==undefined){question.value=props.initialQuestion??'';questionMode.value=props.initialQuestion===null?'null':'text';}}}
function availabilityChanged(value){available.value=value===true&&references.value!==null;}
function inputInvalidated(){epoch++;stopPolling();references.value=null;available.value=false;closePreview();closeTask();}
function resultInvalidated(){epoch++;stopPolling();references.value=null;available.value=false;closePreview();inputNonce.value++;emit('invalidate');}
async function preview(){closePreview();if(!canSubmit.value)return;previewOpen.value=true;previewBusy.value=true;const p=++previewEpoch,t={epoch,identity:identity()},request=selection(),expected={references:references.value,...currentScope.value?.scope?{scope:currentScope.value.scope}:{},...currentScope.value?.patientId?{patientId:currentScope.value.patientId}:{}};const check=()=>current(t)&&previewOpen.value&&p===previewEpoch;try{const response=await previewDeidentificationTask(request,{preview:false});if(!check())return;if(!await verifyDeidentificationContext(response,expected,{current:check}))throw new Error();if(check())previewValue.value={source:response.data.source,question:Object.hasOwn(request,'question')?request.question:null};}catch{if(check()){closePreview();error.value='当前模型预览来源、范围或用途无法核对，未保留旧原文。';}}finally{if(check())previewBusy.value=false;}}
function pending(m){return ['queued','running'].includes(m.status)||m.status==='cancelled'&&m.finish_time===null;}
function schedule(t){stopPolling();if(!current(t)||!metadata.value||!pending(metadata.value))return;timer=setTimeout(async()=>{timer=null;try{const m=(await getDeidentificationSharedTask(runId.value)).data;if(!current(t))return;if(!await verifyDeidentificationSharedMetadata(m,{runId:runId.value,current:()=>current(t)}))throw new Error();const changed=canonical([metadata.value?.status,metadata.value?.part_hashes])!==canonical([m.status,m.part_hashes]);metadata.value=m;if(changed)viewRevision.value++;if(!m.clinical_parts_available){references.value=null;available.value=false;inputNonce.value++;stopPolling();return;}schedule(t);}catch{if(current(t)){closeTask();references.value=null;available.value=false;error.value='当前任务已不可核对，旧候选与选择已清除。';}}},1500);}
async function generate(){if(!canSubmit.value)return;epoch++;closeTask();closePreview();busy.value=true;error.value='';const t={epoch,identity:identity()},body=selection(),caseId=references.value.deidentification_case_id;try{const m=(await createDeidentificationSharedTask(body,{preview:false})).data;if(!current(t))return;if(!await verifyDeidentificationSharedMetadata(m,{caseId,current:()=>current(t)})||!m.clinical_parts_available)throw new Error();if(!current(t))return;submittedInput.value=body;runId.value=m.run_id;metadata.value=m;emit('run-created',m.run_id);schedule(t);}catch{if(current(t)){closeTask();error.value='任务提交或同一Case回执无法核对，未接受外来任务。';}}finally{if(current(t))busy.value=false;}}
function metadataChanged(value){if(value.run_id!==runId.value)return;metadata.value=value;if(!pending(value))stopPolling();}
async function openTask(id){if(!sessionAllowed.value||!uuid(id))return;clearAll();const before=identity();await nextTick();if(!sessionAllowed.value||before!==identity())return;currentScope.value={scope:props.scope,patientId:props.patientId};runId.value=id;}
watch([question,questionMode],()=>{epoch++;stopPolling();busy.value=false;closePreview();closeTask();},{flush:'sync'});
watch([()=>props.feature,()=>props.scope,()=>props.patientId,()=>props.initialReferences,()=>props.initialQuestion,()=>props.active,()=>store.state.user?.accessToken,()=>store.state.user?.username,roles,kept],clearAll,{deep:true,flush:'sync'});onActivated(()=>{kept.value=true;});onDeactivated(()=>{kept.value=false;});onBeforeUnmount(()=>{alive=false;clearAll();});defineExpose({clear:clearAll,openTask});
</script>
